local Test={}
function Test.run()
 local B=require('biology');local M=require('desktop_model');local V=require('vessels');local Rack=require('desktop_rack');local Z=require('desktop_depth');local Art=require('desktop_art');local Host=require('desktop_host');local S=require('persistence')
 local monitors={{id='test',x=0,y=0,w=1920,h=1080,dpi=96}};Host.monitors=monitors;local failed,lines=0,{}
 local function test(name,fn) local ok,why=xpcall(fn,debug.traceback);lines[#lines+1]=(ok and 'PASS ' or 'FAIL ')..name;if not ok then failed=failed+1;lines[#lines+1]=tostring(why) end end
 local function fixture() local s=B.new(1);V.ensure(s);M.ensure(s);local rack=M.add(s,'rack','rack',nil,100,250);local tubes={};for i=1,9 do V.add(s,4,true);tubes[i]=M.add(s,'vial',s.vessels[#s.vessels].id,nil,100,100) end;return s,rack,tubes end
 local function mount(s,r,t,n) for i=1,n or 8 do t[i].config.rack=r.id;t[i].config.slot=i end;Rack.layout(s,r,monitors) end
 test('Eight vial windows and their labels fit in separate rack slots',function() local s,r,t=fixture();mount(s,r,t);assert(r.w==882);for i=1,7 do local w=M.dimensions(t[i],monitors[1]);assert(t[i].x+w<t[i+1].x) end end)
 test('Mixed DPI, vial scale and rack scale preserve nonoverlapping alignment',function() local s,r,t=fixture();local mm={{id='left',x=-2560,y=-200,w=2560,h=1400,dpi=144}};r.x=-2200;r.y=300;r.scale=.7;for i=1,8 do t[i].scale=i%2==0 and 1.8 or .6;t[i].config.rack=r.id;t[i].config.slot=i end;Rack.layout(s,r,mm);for i=1,7 do local w=M.dimensions(t[i],mm[1]);assert(t[i].x+w<t[i+1].x) end;for i=1,8 do assert(math.abs(t[i].y+160*t[i].scale*1.5-(r.y+Rack.slotY*r.scale*1.5))<1) end end)
 test('Rack snapping uses exclusive nearest free slots and rejects a ninth vial',function() local s,r,t=fixture();for i=1,8 do local hit,ok=Rack.drop(s,t[i],{x=r.x+70,y=r.y+54},monitors);assert(hit and ok) end;local seen={};for i=1,8 do assert(not seen[t[i].config.slot]);seen[t[i].config.slot]=true end;local hit,ok=Rack.drop(s,t[9],{x=r.x+70,y=r.y+54},monitors);assert(hit and not ok and not t[9].config.rack) end)
 test('Old narrow racks and duplicate saved slots migrate without losing vial identities or contents',function() local s,r,t=fixture();r.w=320;r.h=118;for i=1,8 do t[i].config.rack=r.id;t[i].config.slot=1 end;local before=S.encode(s.vessels);Rack.layout(s,r,monitors);local seen={};for i=1,8 do assert(not seen[t[i].config.slot]);seen[t[i].config.slot]=true end;local loaded=assert(S.decode('return '..S.encode(s),B));assert(before==S.encode(loaded.vessels));Rack.layoutAll(loaded,monitors);assert(M.find(loaded,r.id).w==882) end)
 test('Rack depth groups keep all vials above the rack while moving together',function() local s,r,t=fixture();mount(s,r,t);Z.move(s,t[1].id,'front');local order=Z.ordered(s);local index={};for i,o in ipairs(order) do index[o.id]=i end;for i=1,8 do assert(index[t[i].id]>index[r.id]) end;local x,y=t[1].x,t[1].y;r.x=r.x+100;r.y=r.y+60;Rack.layout(s,r,monitors);assert(t[1].x==x+100 and t[1].y==y+60) end)
 test('Dragging a racked vial out detaches it instead of snapping back',function() local s,r,t=fixture();mount(s,r,t);local o=t[1];local N=require('native_windows');local old=N.move;N.move=function() end;Host.context={getState=function() return s end};Host.windows[o.id]={};Host.event({type='down',id=o.id,x=40,y=60,cursor={x=o.x+40,y=o.y+60}});Host.event({type='move',id=o.id,x=40,y=60,cursor={x=1500,y=800}});Host.event({type='up',id=o.id,x=40,y=60,cursor={x=1500,y=800}});N.move=old;Host.context=nil;Host.windows={};assert(not o.config.rack and not o.drag) end)
 test('Empty flasks render clear glass; adding a real cell draws suspension; emptying removes it',function() local s=B.new(1);V.ensure(s);M.ensure(s);local v=s.vessels[2];local o=M.add(s,'flask',v.id);local _,empty=Art.render(s,o,1);local _,_,_,alpha=empty:getPixel(70,180);v.contents={{cell=B.cell(s,1),count=1}};local _,full=Art.render(s,o,1);local _,_,_,filledAlpha=full:getPixel(70,180);assert(filledAlpha>alpha+.25);v.contents={};local _,clear=Art.render(s,o,1);local _,_,_,clearAlpha=clear:getPixel(70,180);assert(math.abs(clearAlpha-alpha)<.01 and V.count(v)==0) end)
 test('Render full-width eight-vial rack and empty/occupied flasks',function() local s,r,t=fixture();mount(s,r,t);r.x=15;r.y=140;Rack.layout(s,r,monitors);local canvas=love.graphics.newCanvas(1240,310);love.graphics.push('all');love.graphics.setCanvas(canvas);love.graphics.clear(.035,.055,.065);for _,o in ipairs(Z.ordered(s)) do if o==r or o.config.rack==r.id then love.graphics.push();love.graphics.translate(o.x,o.y);Art.draw(s,o);love.graphics.pop() end end;local empty=M.add(s,'flask',s.vessels[2].id);love.graphics.push();love.graphics.translate(890,20);Art.draw(s,empty);love.graphics.pop();V.add(s,2,true);local v=s.vessels[#s.vessels];v.contents={{cell=B.cell(s,1),count=1}};local full=M.add(s,'flask',v.id);love.graphics.push();love.graphics.translate(1060,20);Art.draw(s,full);love.graphics.pop();love.graphics.setCanvas();local root=love.filesystem.isFused() and love.filesystem.getSourceBaseDirectory() or love.filesystem.getSource();local file=assert(io.open(root..'/equipment-preview.png','wb'));file:write(canvas:newImageData():encode('png'):getString());file:close();love.graphics.pop() end)
 local result=table.concat(lines,'\n')..string.format('\n%d checks; %d failures.\n',#lines,failed);local root=love.filesystem.isFused() and love.filesystem.getSourceBaseDirectory() or love.filesystem.getSource();local f=assert(io.open(root..'/equipment-test-results.txt','wb'));f:write(result);f:close();assert(failed==0,result);return result
end
return Test
